```
```go
// Go binding sketch
package main
/*
#include "quantile.h"
#include <stdlib.h>
*/
import "C"
import (
  "fmt"
  "unsafe"
)
func ComputeQuantiles(data []float64, k int) ([]float64, error) {
  if k <= 0 { return nil, fmt.Errorf("k must be >0") }
  n := len(data)
  if n == 0 { return nil, fmt.Errorf("data empty") }
  out := make([]float64, k)
  var status C.int
  C.compute_quantiles((*C.double)(unsafe.Pointer(&data[0])), C.size_t(n), (*C.double)(unsafe.Pointer(&out[0])), C.size_t(k), &status)
  if status != 0 { return nil, fmt.Errorf("quantiles failed, status=%d", status) }
  return out, nil
}
```

