func (h *Hasher) Write(p []byte) (int, error) { C.hasher_update(h.c, unsafe.Pointer(&p[0]), C.size_t(len(p))); return len(p), nil }
func (h *Hasher) SumHex() (string, error) { digest := make([]byte, 32); C.hasher_finalize(h.c, (*C.uchar)(&digest[0])); C.hasher_free(h.c); return hex.EncodeToString(digest), nil }
